}

protected override void Draw(GameTime gameTime)
{
    if (_headless) return;              // Line 179 — early-return in headless (Examples ONLY)
    _screenController.Draw(gameTime);   // Line 180
}
```

**File:** `/Users/rodrigooliveira/.warp/worktrees/monodreams/feat/level-editor/MonoDreams.Demos/Game1.cs:130-148` (Demos host — rendering always runs)

```csharp
protected override void Update(GameTime gameTime)
{
    if (!_headless.Enabled && Keyboard.GetState().IsKeyDown(Keys.Q))
        Exit();
    _screenController.Update(gameTime);  // Line 136
}

protected override void Draw(GameTime gameTime)
{
    // Headless deliberately does NOT early-return here (unlike the Examples host):
    // rendering every frame is what makes screenshots and render-path memory
    // behaviour observable.
    _screenController.Draw(gameTime);    // Line 144 — NO EARLY RETURN

