**File:** `/Users/rodrigooliveira/.warp/worktrees/monodreams/feat/level-editor/MonoDreams/foundation/Screen/ScreenController.cs:45-63`

```csharp
public void Update(GameTime gameTime)
{
    if (_screen.next != null)
    {
        _screen.current?.Dispose();
        _screen.current = _screen.next;
        _screen.next = null;
        _screen.current.Load(this, Content);
    }

    _state.Update(gameTime);                    // GameState updated here (line 55)
    Logger.UpdateGameTime(_state.TotalTime);
    _screen.current?.UpdateSystem.Update(_state); // UpdateSystem invoked (line 57)
}

